<section id="h2-contact" data-8b-section="contact" aria-labelledby="h2-contact-title">
  <h2 class="m-text-3 contact__title" id="h2-contact-title" style="--len:10"><span class="contact__voice">Let's talk</span><span class="m-dot" aria-hidden="true"></span></h2>
  <div class="contact__grid">
    <div class="contact__info">
      <p class="m-text-5 contact__lead">Tell us what you want to achieve. Our marketing specialists review every inquiry and reply within 24 hours.</p>
      <a data-8b-placeholder="email" class="contact__mail" href="mailto:contact@betterinsights.in"><span>contact@betterinsights.in</span></a>
      <dl class="contact__places">
        <div><dt class="m-text-7">Pune Office</dt><dd class="m-text">Office No. 828, Clover Hills Plaza<br>Undri Pisoli Road, Kondhwa, Pune – 411048</dd><dd class="m-text"><a data-8b-placeholder="phone" href="tel:+919509996730">+91 950 999 6730</a></dd></div>
        <div><dt class="m-text-7">Maharashtra, India</dt><dd class="m-text">Better Insights Digital Consulting<br>contact@betterinsights.in</dd><dd class="m-text"><a data-8b-placeholder="phone" href="tel:+919509996730">+91 950 999 6730</a></dd></div>
      </dl>
    </div>
    <form data-8b-placeholder="form" class="contact__form m-surface" novalidate>
      <div class="contact__pair">
        <label class="m-text-6">Your name<input class="m-field" name="name" type="text" autocomplete="name" required></label>
        <label class="m-text-6">Email<input class="m-field" name="email" type="email" autocomplete="email" required></label>
      </div>
      <div class="contact__pair">
        <label class="m-text-6">Company<input class="m-field" name="company" type="text" autocomplete="organization"></label>
        <label class="m-text-6">What can we help with?<select class="m-field" name="topic"><option>SEO &amp; Organic Growth</option><option>Google &amp; Meta Ads</option><option>Website Design &amp; Development</option><option>Social Media Marketing</option><option>Branding &amp; PR</option><option>Comprehensive Marketing Plan</option></select></label>
      </div>
      <label class="m-text-6">A few words about the project<textarea class="m-field" name="message" rows="3" required></textarea></label>
      <div class="contact__actions">
        <button class="m-btn" type="submit"><span class="m-btn__label">Send message</span></button>
        <p class="m-text contact__status" role="status" aria-live="polite" data-success="Thank you. Our marketing team will review your enquiry and reply within 24 hours." data-error="Please add your name, a valid email, and details about your marketing goals."></p>
      </div>
    </form>
  </div>
</section>
